scwin.vScrenID = "ULDSTF05916.xml";
scwin.fr_SecuGrpId = SECUGRP_ID_EW;
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_search = function() {
    var url = "/Delisting.do?method=searchDelList" + "&DIV_IDX=" + DIV_IDX_DELLIST_LIST + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD.BindColVal;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts.DataID = encodeURI(url);
    dts.reset();
    $c.cm.ShowWin(grd);
};
scwin.fn_search2 = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=DELLIST_MST_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.dellist.lstttrd_dd.list.select" + "&{P}ISUR_CD=99999";
    dts2.DataID = encodeURI(url);
    dts2.reset();
    $c.cm.ShowWin(grd2);
};
scwin.fn_search3 = function() {
    var url = "/Delisting.do?method=searchDelList" +
        //				      "&DIV_IDX="+DIV_IDX_DELLIST_LIST_KO + "&TRS_IDX="+TRS_IDX_SELECT + "&ISUR_CD=99999"  ;
        "&DIV_IDX=" + DIV_IDX_DELLIST_LIST_KO + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=99999" + "&GUBUN_CD=" + "690019";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts3.DataID = encodeURI(url);
    dts3.reset();
    $c.cm.ShowWin(grd3);
};
scwin.fn_search4 = function() {
    var url = "/Delisting.do?method=searchDelList" + "&DIV_IDX=" + DIV_IDX_DELLIST_LIST_TRD + "&TRS_IDX=" + TRS_IDX_SELECT + "&GUBUN_CD=" + "690020";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
