scwin.fn_newpre_create_frame = async function() {
    await $c.frame.CreateDialogFrame("DLG_DELLIST", "../lstproc/ULDSTF05917.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 상장폐지", 200, 100, 720, 530, "window");
    scwin.fn_search(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};
