//elw발행사
scwin.fn_get_isurcode = function() {
    dts_ElwInst.DataID = "/CodeAction.do?method=listWrntCd&For=C";
    dts_ElwInst.Reset();
    dts_ElwUly.DataID = "/CodeAction.do?method=listElwUlyCd&For=C";
    dts_ElwUly.Reset();
};
scwin.img_Elwlist_OnSelChanged = function(nIndex) {
    if (nIndex == 2) {
        scwin.fn_search2();
    } else if (nIndex == 3) {
        scwin.fn_search3();
    } else if (nIndex == 4) {
        scwin.fn_search4();
    } else if (nIndex == 5) {
        scwin.fn_search5();
    }
};
scwin.img_Search_onclick = function() {
    if (cmb_ISUR_CD.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0016", ""));
        cmb_ISUR_CD.focus();
        return;
    }
    scwin.fn_search();
};
scwin.img_Search2_onclick = function() {
    scwin.fn_search2();
};
scwin.img_Search3_onclick = function() {
    scwin.fn_search3();
};
scwin.img_Search4_onclick = function() {
    scwin.fn_search4();
};
scwin.img_Search5_onclick = function() {
